/*==================================*
 * LEARNING MODULE HELPER FUNCTIONS
 *==================================*/

/*
 * Get a module by module ID
 */

function getLearningModule(moduleId) {

    return LEARNING_MODULES.find(
        module => module.moduleId === Number(moduleId)
    );

}


/*
 * Get a lesson by module ID and lesson ID
 */

function getLearningLesson(moduleId, lessonId) {

    const module =
        getLearningModule(moduleId);

    if (!module) {
        return null;
    }

    return module.topics.find(
        lesson =>
            lesson.lessonId === Number(lessonId)
    ) || null;

}


/*
 * Get first available lesson
 */

function getFirstLearningLesson(moduleId) {

    const module =
        getLearningModule(moduleId);

    if (!module || !module.topics.length) {
        return null;
    }

    return module.topics.find(
        lesson => lesson.locked === false
    ) || null;

}


/*
 * Get total lessons
 */

function getTotalLessons(moduleId) {

    const module =
        getLearningModule(moduleId);

    if (!module) {
        return 0;
    }

    return module.topics.length;

}


/*
 * Get completed lessons
 */

function getCompletedLessons(moduleId) {

    const module =
        getLearningModule(moduleId);

    if (!module) {
        return 0;
    }

    return module.topics.filter(
        lesson => lesson.completed === true
    ).length;

}


/*
 * Get module progress percentage
 */

function getModuleProgress(moduleId) {

    const total =
        getTotalLessons(moduleId);

    const completed =
        getCompletedLessons(moduleId);

    if (total === 0) {
        return 0;
    }

    return Math.round(
        (completed / total) * 100
    );

}